/**
 * Build-time only: `npm run build` calls prerender() once per address listed in
 * data/routes.json (generated by tools/build_index.py) and saves the result as
 * <address>/index.html, so every album and song is a real page for search engines.
 */
import { App } from './App';
import { setReaders } from './lib/api';
import { describe } from './lib/meta';
import { parsePath } from './lib/router';
import { preloadRoute } from './lib/preload';

const SITE_URL = 'https://fftabs.com';

export async function prerender({ url }: { url: string }) {
  // Node's file reader, fetched at run time so the bundler doesn't swap it for a browser stub
  const { readFile } = process.getBuiltinModule('node:fs/promises');
  // server-only, imported here so it never ends up in the browser bundle
  const { renderToString } = await import('preact-render-to-string');

  // read content straight from the repo instead of fetching it
  setReaders({
    json: async (path) => JSON.parse(await readFile(path, 'utf8')),
    bytes: async (path) => {
      const b = await readFile(path);
      return b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength) as ArrayBuffer;
    },
  });

  const route = parsePath(url);
  await preloadRoute(route);
  const html = renderToString(<App route={route} />);
  const { title, description } = describe(route);
  const canonical = SITE_URL + url;

  return {
    html,
    // added to each page's <head> (index.html stays a bare template)
    head: {
      lang: 'en',
      title,
      elements: new Set([
        { type: 'meta', props: { name: 'description', content: description } },
        { type: 'link', props: { rel: 'canonical', href: canonical } },
        { type: 'meta', props: { property: 'og:type', content: 'website' } },
        { type: 'meta', props: { property: 'og:site_name', content: 'fftabs' } },
        { type: 'meta', props: { property: 'og:title', content: title } },
        { type: 'meta', props: { property: 'og:description', content: description } },
        { type: 'meta', props: { property: 'og:url', content: canonical } },
      ]),
    },
  };
}
